// The standard window frame and small DOM helpers, without React: what 'tilr/ui' exports as
// `frame()`, `element()` and `frameControls()`. One description of the frame for every copy of
// it: `frame()` (a plugin that draws with the DOM), the React `<Frame>` (tilr/ui.tsx) and
// `ctx.ui.tile()` (runtime.ts) all draw their buttons from `frameControls()` and their parts with
// `FRAME`'s classes, so the markup, the aria-labels and the `data-call`s cannot drift apart.
// Built to site/dom.js; tilr/ui.js and runtime.js import it relatively (one module in the page).
import type { WindowHandle } from './types.ts'

/** The parts of the standard frame: `<section class="tile"><header data-window-drag>` (the title
 *  bar, the drag handle), `<div class="controls">` (its buttons), `<div class="body">`. */
export const FRAME = {
  tile: 'tile',
  controls: 'controls',
  body: 'body',
  /** The attribute of the drag handle: the layout drags a window by the element that has it. */
  drag: 'data-window-drag',
} as const

/** What the frame's buttons need of a window. */
export type FrameWindow = Pick<WindowHandle, 'mode' | 'modes' | 'close' | 'requestFloat' | 'requestTile'>

/** One button of the standard frame. */
export interface FrameControl {
  /** Its marker attribute, `data-float` or `data-close`: what a test or a stylesheet finds it by. */
  readonly id: 'float' | 'close'
  /** Its aria-label: every control is named, for an agent reading a snapshot. */
  readonly label: string
  readonly text: string
  /** Its `data-call`: the layout's method it stands for (`layout.float`, `layout.tile`,
   *  `layout.close`), for an agent reading a snapshot. */
  readonly call: string
  /** What a click does, read off the window at the time of the click. */
  run(): void
}

/**
 * The buttons of the standard frame for the window as it is now: float / tile (only for a type
 * with two modes or more) and close. Draw them again when `mode` or `modes` change; `frame()`
 * and `<Frame>` do.
 */
export function frameControls(win: FrameWindow): FrameControl[] {
  const controls: FrameControl[] = []
  if (win.modes.length > 1) {
    controls.push({
      id: 'float',
      label: 'float or tile',
      text: '⧉',
      call: win.mode === 'float' ? 'layout.tile' : 'layout.float',
      run: () => win.mode === 'float' ? win.requestTile() : win.requestFloat(),
    })
  }
  controls.push({ id: 'close', label: 'close', text: '×', call: 'layout.close', run: () => win.close() })
  return controls
}

/**
 * Draws `frameControls(win)` as buttons into `host` (after what it holds already: a plugin's own
 * controls go first) and keeps them current: `data-call` follows the mode, the float button
 * comes and goes with `modes`. Returns the undo, which removes the buttons. The buttons keep
 * their identity across updates (focus survives a float).
 */
export function drawControls(host: HTMLElement, win: FrameWindow & Pick<WindowHandle, 'subscribe'>): () => void {
  const buttons = new Map<FrameControl['id'], { button: HTMLButtonElement, control: FrameControl }>()
  const draw = () => {
    const controls = frameControls(win)
    for (const [id, { button }] of buttons) {
      if (!controls.some(control => control.id === id)) { button.remove(); buttons.delete(id) }
    }
    let before: HTMLButtonElement | null = null
    for (const control of [...controls].reverse()) {
      let entry = buttons.get(control.id)
      if (!entry) {
        const button = document.createElement('button')
        button.type = 'button'
        button.setAttribute(`data-${control.id}`, '')
        const created = { button, control }
        button.addEventListener('click', () => created.control.run())
        buttons.set(control.id, entry = created)
      }
      entry.control = control
      const { button } = entry
      if (button.getAttribute('aria-label') !== control.label) button.setAttribute('aria-label', control.label)
      if (button.dataset.call !== control.call) button.dataset.call = control.call
      if (button.textContent !== control.text) button.textContent = control.text
      if (button.parentElement !== host || button.nextElementSibling !== before) host.insertBefore(button, before)
      before = button
    }
  }
  draw()
  const unsubscribe = win.subscribe(draw, ['mode', 'modes'])
  return () => {
    unsubscribe()
    for (const { button } of buttons.values()) button.remove()
    buttons.clear()
  }
}

/** `frame()`'s options. */
export interface FrameOptions {
  /** More classes on the `<section class="tile">`: `'browser-tile'`. */
  className?: string
  /** The title bar's text. Omitted: the window's title, kept current. `null`: left alone (the
   *  plugin writes the header itself). */
  title?: string | null
  /** The float / tile and close buttons (default true). Without them `controls` is empty. */
  controls?: boolean
}

/** What `frame()` returns: the parts, and the undo. */
export interface FrameParts {
  /** The `<section class="tile">`: append it to the window's host. */
  tile: HTMLElement
  /** The title bar, the drag handle. */
  header: HTMLElement
  /** The buttons' row; a plugin's own controls may be prepended. */
  controls: HTMLElement
  /** Where the window's content goes. */
  body: HTMLElement
  /** Stops following the window and removes the tile. */
  dispose(): void
}

/**
 * The standard frame for a window drawn with the DOM, what `<Frame>` is for React: the title bar
 * (the drag handle), the float / tile and close buttons (with aria-labels and `data-call`, the
 * float one only for a type with two modes or more) and the body.
 *
 *   mount(host, win) {
 *     const { tile, body, dispose } = frame(win, { className: 'clock-tile' })
 *     body.append(element('div', 'big', 'hello'))
 *     host.append(tile)
 *     return dispose
 *   }
 */
export function frame(win: FrameWindow & Pick<WindowHandle, 'title' | 'subscribe'>, options: FrameOptions = {}): FrameParts {
  const tile = element('section', options.className ? `${FRAME.tile} ${options.className}` : FRAME.tile)
  const header = element('header')
  header.setAttribute(FRAME.drag, '')
  const controls = element('div', FRAME.controls)
  const body = element('div', FRAME.body)
  tile.append(header, controls, body)
  const undo: (() => void)[] = []
  if (options.controls !== false) undo.push(drawControls(controls, win))
  if (options.title !== undefined) {
    if (options.title !== null) header.textContent = options.title
  } else {
    const title = () => { if (header.textContent !== win.title) header.textContent = win.title }
    title()
    undo.push(win.subscribe(title, ['title']))
  }
  let disposed = false
  return {
    tile, header, controls, body,
    dispose() {
      if (disposed) return
      disposed = true
      for (const fn of undo.reverse()) fn()
      tile.remove()
    },
  }
}

/** `document.createElement(tag)` with a class and a text: `element('div', 'row', name)`. */
export function element<K extends keyof HTMLElementTagNameMap>(tag: K, className?: string, text?: string): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag)
  if (className) el.className = className
  if (text !== undefined) el.textContent = text
  return el
}
